Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation cellA := (cell Asan.M.loaded_segments).
#[local] Abbreviation wrA := (wr Asan.M.loaded_segments).
#[local] Notation "'U' r" := (bv_unsigned r) (at level 10, r at level 9).

Ltac rok_open14 ROK :=
  destruct ROK as (GEO & Esb & Kal & Kspb & Kend & Pal & Plo & Phi & Papp & Hkey & Hloff & Hloff' & Hloff'' & Htpd & Htsdd & Dl2 & Dblk
                   & Al2t & Al2c & Al2k & Al2s & Abt & Abc & Abk & Abs & Apt & Apc & Apk & Apl & Apb & Aft & Afc & Afk & Afl & Afb & Afp & Fhi & Fapp & Fimg & Flo
                   & Il2 & Iblk & Afkb & D0 & D1 & D2 & D3 & Adt & Adc & Adk & Adp & Adl & Adb & Adf & Atkb & Ackb & Al2kb & Apkb).

(* [comment removed for export] *)
Definition art_sec_dflt : art_sec := SEC 0 0 0 0 false.
Definition art_gs_freeP {FSG : Type} (G : art_gs FSG) (idx : nat) (mb ms : Z) (kb : nat) : art_gs FSG := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S02lcd;g0d;<scd;$FSG;R{cd;$G;R!1+0#1$idx;R+1$mb;R+2$ms;R+2$kb;R+1!<,3#6!3'4+5!2'6#6#5!3'4+5!2'7#3#2!3,8+5!2,9#3#2!1,:+5!2';#6#5!2'<#6#5!2'=#6#5!4'>+?'@#4!2'A#6#5!2'B#6#5!2'C#6#5!2'D#6#5#1,E!2'F#6#5").

Section RepP.
Variable FSG : Type.
Variables (rn : art_run) (G : art_gs FSG) (LB : list (Z * Z)) (M M' : word -> option byte).
Variables (Sp u n mb ms : Z) (idx : nat) (s : art_sec) (kb : nat).
Let bl := map art_sec_b (g_sec FSG G).
Let last := fst (nth (length bl - 1) bl (0, 0)).
Let G' := art_gs_freeP G idx mb ms kb.

Hypothesis REP : art_alloc_rep FSG rn G LB M.
Hypothesis Hin : In (u, n) LB.
Hypothesis Hn : 2 ^ 28 < n < 2 ^ 39.
Hypothesis Hidx : nth_error (g_sec FSG G) idx = Some s.
Hypothesis Hsq : sc_quar s = false.
Hypothesis Hsu : sc_u s = u.
Hypothesis Hsn : sc_n s = n.
Hypothesis Hsm : sc_map s = mb.
Hypothesis Hsms : sc_msize s = ms.
Hypothesis HS : rn_HI rn + 4096 <= Sp - 4096.
Hypothesis HS47 : Sp < 2 ^ 47.
Hypothesis Edep : g_depot FSG G = Datatypes.S kb.
Hypothesis OUT : art_free3P_out M M' Sp (rn_t rn) u (rn_l2 rn) (rn_blk rn) (rn_parr rn) mb ms bl idx kb.
Hypothesis LIVE : forall p, In p (art_live (g_log FSG G)) ->
  0 < fst p /\ 0 < snd p /\ fst p + snd p <= rn_HI rn /\ (fst p + snd p <= 0x7fff7000 \/ 0x10007fff8000 <= fst p)
  /\ (forall o, In o (art_objs rn) -> apart (fst p) (snd p) (fst o) (snd o)).
Hypothesis LIVE2 : forall p p', In p (art_live (g_log FSG G)) -> In p' (art_live (g_log FSG G)) -> fst p <> fst p' -> apart (fst p) (snd p) (fst p') (snd p').
Hypothesis LIVE3 : forall p, In p (art_live (g_log FSG G)) -> fst p mod 4096 = 0 /\ snd p mod 4096 = 0.
Hypothesis LIVEND : List.NoDup (map fst (art_live (g_log FSG G))).
Hypothesis Hother : forall b0, In b0 (lb_remove u LB) -> In b0 LB /\ fst b0 <> u.

(* [comment removed for export] *)
Lemma art_fP_out :
  art_agree (art_free3P_fpall Sp (rn_t rn) u (rn_l2 rn) (rn_blk rn) (rn_parr rn) (Z.of_nat idx) last mb ms) M M'
  /\ (forall x : word, mb <= U x < mb + ms -> M' x = None)
  /\ (forall x : word, SB + mb / 8 <= U x < SB + mb / 8 + ms / 8 -> M' x = Some (Z_to_bv 8 0))
  /\ (forall a k, 0 <= a -> a + k < 2 ^ 64 -> apart mb ms a k -> wrA M a k -> wrA M' a k)
  /\ art_sec_cells M' (rn_parr rn) (art_swap_remove (0, 0) idx bl)
  /\ DInvD (rn_l2 rn) (rn_blk rn) kb M'
  /\ cellA M' (rn_t rn + 3168) 1 0
  /\ cellA M' 0x1f9988 4 1 /\ (forall k, 0 <= k < 2 ^ 15 -> cellA M' (0x16b108 + 8 * k) 8 0).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00/OUT;").
Qed.

